def _prefixed(domain: str, digest: str) -> str:
    prefix = IM.PREFIX.get(domain)
    if not prefix or not isinstance(digest, str):
        return digest
    if digest.startswith(prefix + ":"):
        return digest
    return prefix + ":" + digest


